/**
 * Brand marks (0.9, design language §4): the Teleply logo only from the final asset (brand/mark.svg, the path the web's
 * account page draws), black on light and white on dark; Codex, Claude and DeepSeek keep their own marks: Claude and
 * DeepSeek in their colours (paths from Simple Icons, CC0), Codex in one colour (0.9.1, see [Codex]).
 */
object TeleplyBrand {
    /** The Teleply mark: a screen with a prompt beside a phone; 1000 × 822, filled with the tint. */
    val Mark: ImageVector by lazy {
        ImageVector.Builder(name = "teleply", defaultWidth = 30.dp, defaultHeight = 24.66.dp, viewportWidth = 1000f, viewportHeight = 822f).apply {
            addPath(pathData = addPathNodes(MARK), fill = SolidColor(Color.Black))
        }.build()
    }
    /**
     * Codex (0.9.1): OpenAI's Codex mark, the scalloped cloud with a ">_" prompt cut out (openai.com/codex), in one colour
     * as OpenAI's own sidebar shows it. OpenAI publishes no file of it for others: this path is SVG Logos' tracing
     * (github.com/gilbarbara/logos, logos/codex.svg, CC0, added 2026-09-05), which matches the official shape. The mark
     * itself belongs to OpenAI. Until 0.9 a generic "</>" stood here, as it still does on the web. The cloud fills its
     * whole box, so it is drawn a little smaller to weigh the same as the Claude and DeepSeek marks beside it.
     */
    val Codex: ImageVector by lazy {
        ImageVector.Builder(name = "codex", defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = CodexBox, viewportHeight = CodexBox).apply {
            group(translationX = (CodexBox - 256f) / 2f, translationY = (CodexBox - 256f) / 2f) {
                addPath(pathData = addPathNodes(CODEX), fill = SolidColor(Color.Black), pathFillType = PathFillType.EvenOdd)
            }
        }.build()
    }
    /** The Codex path's 256 box with room around it: the cloud shows at about 21/24 of the mark's size. */
    private const val CodexBox = 292f
    val Claude: ImageVector by lazy { filled("claude", CLAUDE) }
    val DeepSeek: ImageVector by lazy { filled("deepseek", DEEPSEEK) }

    /** Brand colours (web: .mark.claude #d97757, .mark.deepseek #4d6bfe; Codex ink, white text colour on dark). */
    val ClaudeColor = Color(0xFFD97757)
    val DeepSeekColor = Color(0xFF4D6BFE)

    private fun filled(name: String, d: String) =
        ImageVector.Builder(name = name, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 24f, viewportHeight = 24f).apply {
            addPath(pathData = addPathNodes(d), fill = SolidColor(Color.Black))
        }.build()

