/** A source's own mark in its colour (web sidebar): Codex in the text colour, Claude orange, DeepSeek blue. */
@Composable
fun SourceMark(app: String, modifier: Modifier = Modifier, size: Dp = 24.dp) {
    val p = LocalTeleply.current
    val (vector, tint) = when (app) {
        "claude" -> TeleplyBrand.Claude to TeleplyBrand.ClaudeColor
        "deepseek" -> TeleplyBrand.DeepSeek to TeleplyBrand.DeepSeekColor
        else -> TeleplyBrand.Codex to if (p.dark) p.text else Color(0xFF1E222A)
    }
    Icon(vector, contentDescription = null, tint = tint, modifier = modifier.size(size))
}

/** The Teleply mark at [width], black on light pages and white on dark ones (design language §4). */
@Composable
fun TeleplyLogo(modifier: Modifier = Modifier, width: Dp = 30.dp) {
    val p = LocalTeleply.current
    Icon(TeleplyBrand.Mark, contentDescription = null, tint = if (p.dark) Color.White else Color(0xFF111113), modifier = modifier.size(width, width * 0.822f))
}
